48	  const after = new Map(afterEntries.map(entry => [entry.key, entry.summary]))
49	  const rows = []
50	  const missingInAfter = []
51	  const missingInBefore = []
52	  for (const [key, beforeSummary] of before) {
53	    const afterSummary = after.get(key)
54	    if (afterSummary === undefined) continue
55	    const metrics = new Set([...Object.keys(beforeSummary.metrics ?? {}), ...Object.keys(afterSummary.metrics ?? {})])
56	    for (const metric of metrics) {
57	      const inBefore = beforeSummary.metrics?.[metric] !== undefined
58	      const inAfter = afterSummary.metrics?.[metric] !== undefined
59	      if (inBefore && !inAfter) missingInAfter.push({ key, metric })
60	      if (!inBefore && inAfter) missingInBefore.push({ key, metric })
61	    }
62	    for (const metric of metrics) {
63	      for (const percentile of ['p50', 'p95', 'p99']) {
64	        const beforeValue = beforeSummary.metrics?.[metric]?.[percentile]
65	        const afterValue = afterSummary.metrics?.[metric]?.[percentile]
66	        if (typeof beforeValue !== 'number' || typeof afterValue !== 'number') continue
67	        const deltaMs = afterValue - beforeValue
68	        const deltaPercent = beforeValue === 0 ? null : (deltaMs / beforeValue) * 100
69	        rows.push({ key, metric, percentile, before: beforeValue, after: afterValue, deltaMs, deltaPercent })
70	      }
71	    }
72	  }
73	  return { rows, missingInAfter, missingInBefore }
74	}
75	
76	const beforeEntries = await load(positional[0])
77	const afterEntries = await load(positional[1])
78	const beforeKeys = new Set(beforeEntries.map(entry => entry.key))
79	const afterKeys = new Set(afterEntries.map(entry => entry.key))
80	const metricComparison = metricRows(beforeEntries, afterEntries)
81	const { rows } = metricComparison
82	const regressions = maxRegression === undefined
83	  ? []
84	  : rows.filter(row => row.deltaPercent !== null && row.deltaPercent > maxRegression)
85	const report = {
86	  before: positional[0],
87	  after: positional[1],
88	  maxRegressionPercent: maxRegression ?? null,
89	  missingInAfter: [...beforeKeys].filter(key => !afterKeys.has(key)),
90	  missingInBefore: [...afterKeys].filter(key => !beforeKeys.has(key)),
91	  missingMetricsInAfter: metricComparison.missingInAfter,
92	  missingMetricsInBefore: metricComparison.missingInBefore,
93	  rows,
94	  regressions,
95	}
96	
97	if (json) {
98	  console.log(JSON.stringify(report, null, 2))
99	} else {
100	  console.log(`before: ${report.before}`)
101	  console.log(`after:  ${report.after}`)
102	  if (report.missingInAfter.length > 0) console.log(`missing in after: ${report.missingInAfter.join(', ')}`)
103	  if (report.missingInBefore.length > 0) console.log(`missing in before: ${report.missingInBefore.join(', ')}`)
104	  if (report.missingMetricsInAfter.length > 0) console.log(`missing metrics in after: ${report.missingMetricsInAfter.map(entry => `${entry.key}.${entry.metric}`).join(', ')}`)
105	  if (report.missingMetricsInBefore.length > 0) console.log(`missing metrics in before: ${report.missingMetricsInBefore.map(entry => `${entry.key}.${entry.metric}`).join(', ')}`)
106	  for (const row of rows) {
107	    const delta = row.deltaPercent === null ? 'n/a' : `${row.deltaPercent >= 0 ? '+' : ''}${row.deltaPercent.toFixed(1)}%`
108	    console.log(`${row.key} ${row.metric}.${row.percentile}: ${row.before.toFixed(3)}ms -> ${row.after.toFixed(3)}ms (${delta})`)
109	  }
